public int primDense(int n, int[][] edges) {
    long[][] w = new long[n][n];
    for (long[] row : w) Arrays.fill(row, Long.MAX_VALUE);
    for (int[] e : edges) {
        w[e[0]][e[1]] = Math.min(w[e[0]][e[1]], e[2]);
        w[e[1]][e[0]] = Math.min(w[e[1]][e[0]], e[2]);
    }
    long[] key = new long[n];
    Arrays.fill(key, Long.MAX_VALUE);
    boolean[] inTree = new boolean[n];
    key[0] = 0;
    long total = 0;
    for (int it = 0; it < n; it++) {
        int u = -1;
        for (int v = 0; v < n; v++)
            if (!inTree[v] && (u == -1 || key[v] < key[u])) u = v;
        if (key[u] == Long.MAX_VALUE) return -1;   // disconnected
        inTree[u] = true;
        total += key[u];
        for (int v = 0; v < n; v++)
            if (!inTree[v] && w[u][v] < key[v]) key[v] = w[u][v];
    }
    return (int) total;
}

