def prim_dense(self, n: int, edges: list[list[int]]) -> int:
    INF = float('inf')
    w = [[INF] * n for _ in range(n)]
    for u, v, wt in edges:
        w[u][v] = min(w[u][v], wt)
        w[v][u] = min(w[v][u], wt)
    key = [INF] * n
    in_tree = [False] * n
    key[0] = 0
    total = 0
    for _ in range(n):
        u = -1
        for v in range(n):
            if not in_tree[v] and (u == -1 or key[v] < key[u]):
                u = v
        if key[u] == INF:
            return -1                    # disconnected
        in_tree[u] = True
        total += key[u]
        for v in range(n):
            if not in_tree[v] and w[u][v] < key[v]:
                key[v] = w[u][v]
    return total

