public int prim(int n, int[][] edges) {
    List<int[]>[] adj = new List[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (int[] e : edges) {
        adj[e[0]].add(new int[]{e[1], e[2]});
        adj[e[1]].add(new int[]{e[0], e[2]});
    }

    boolean[] inTree = new boolean[n];
    PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    heap.offer(new long[]{0, 0});       // (weight, start vertex)

    long total = 0;
    int count = 0;
    while (!heap.isEmpty() && count < n) {
        long[] top = heap.poll();
        long w = top[0];
        int u = (int) top[1];
        if (inTree[u]) continue;        // stale crossing edge
        inTree[u] = true;
        total += w;
        count++;
        for (int[] e : adj[u]) {
            if (!inTree[e[0]]) heap.offer(new long[]{e[1], e[0]});
        }
    }
    return count == n ? (int) total : -1;  // disconnected → -1
}

